#define filmGrainIntensity 0.1;

// Inspired by https://www.shadertoy.com/view/wdyczG
// Licensed under the Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported License:
// https://creativecommons.org/licenses/by-nc-sa/3.0/deed.en
mat2 Rot(float a) {
    float s = sin(a);
    float c = cos(a);
    return mat2(c, -s, s, c);
}

vec2 hash(vec2 p) {
    p = vec2(dot(p, vec2(2127.1, 81.17)), dot(p, vec2(1269.5, 283.37)));
    return fract(sin(p)*43758.5453);
}

float noise(in vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    vec2 u = f*f*(3.0-2.0*f);

    float n = mix(mix(dot(-1.0+2.0*hash(i + vec2(0.0, 0.0)), f - vec2(0.0, 0.0)),
    dot(-1.0+2.0*hash(i + vec2(1.0, 0.0)), f - vec2(1.0, 0.0)), u.x),
    mix(dot(-1.0+2.0*hash(i + vec2(0.0, 1.0)), f - vec2(0.0, 1.0)),
    dot(-1.0+2.0*hash(i + vec2(1.0, 1.0)), f - vec2(1.0, 1.0)), u.x), u.y);
    return 0.5 + 0.5*n;
}

float filmGrainNoise(in vec2 uv) {
    return length(hash(vec2(uv.x, uv.y)));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    float aspectRatio = iResolution.x / iResolution.y;

    // Transformed uv
    vec2 tuv = uv - .5;

    // Rotate with noise
    float degree = noise(vec2(iTime*.05, tuv.x*tuv.y));

    tuv.y *= 1./aspectRatio;
    tuv *= Rot(radians((degree-.5)*720.+180.));
    tuv.y *= aspectRatio;

    // Wave warp with sine
    float frequency = 5.;
    float amplitude = 30.;
    float speed = iTime * 2.;
    tuv.x += sin(tuv.y*frequency+speed)/amplitude;
    tuv.y += sin(tuv.x*frequency*1.5+speed)/(amplitude*.5);


    // Light gradient colors
    vec3 forestGreen = vec3(84, 141, 72) / vec3(255);  // Forest Green (#548D48)
    vec3 asparagus = vec3(116, 170, 59) / vec3(255);   // Asparagus (#74AA3B)
    vec3 appleGreen = vec3(145, 186, 66) / vec3(255);  // Apple Green (#91BA42)
    vec3 yellowGreen = vec3(179, 192, 74) / vec3(255); // Yellow Green (#B3C04A)

    // Dark gradient colors
    vec3 olivine = vec3(149, 183, 123) / vec3(255);       // Olivine (#95B77B)
    vec3 resedaGreen = vec3(111, 118, 75) / vec3(255);    // Reseda Green (#6F764B)
    vec3 drabDarkBrown = vec3(40, 37, 18) / vec3(255);    // Drab Dark Brown (#282512)
    vec3 drabDarkBrown2 = vec3(66, 67, 34) / vec3(255);   // Drab Dark Brown 2 (#424322)
    vec3 sage = vec3(189, 186, 154) / vec3(255);          // Sage (#BDBA9A)
    vec3 hookersGreen = vec3(97, 121, 107) / vec3(255);   // Hooker's Green (#61796B)

    // Interpolate between light and dark gradient
    float cycle = sin(iTime * 0.5);
    float t = (sign(cycle) * pow(abs(cycle), 0.6) + 1.) / 2.;
    vec3 color1 = mix(forestGreen, olivine, t);
    vec3 color2 = mix(asparagus, resedaGreen, t);
    vec3 color3 = mix(appleGreen, sage, t);
    vec3 color4 = mix(yellowGreen, hookersGreen, t);

    // Blend the gradient colors and apply transformations
    vec3 layer1 = mix(color3, color2, smoothstep(-.03, .2, (tuv * Rot(radians(-5.))).x));
    vec3 layer2 = mix(color4, color1, smoothstep(-.02, .2, (tuv * Rot(radians(-5.))).x));

    vec3 color = mix(layer1, layer2, smoothstep(.05, -.3, tuv.y));

    // Apply brightness increase and contrast boost
    color = color * 1.;  // Increase brightness
    color = pow(color, vec3(1.2));  // Apply contrast boost

    // Apply film grain
    color = color - filmGrainNoise(uv) * filmGrainIntensity;

    fragColor = vec4(color, 1.0);
}
